from pathlib import Path
p=Path('lib/environment_control/src/climate/ClimatePolicy.cpp')
s=p.read_text()
start=s.index('    if (outside_temperature_ok) {',s.index('  if (input.capabilities.exhaust_fan) {'))
end=s.index('\n  }\n\n  if (input.targets.co2_enabled',start)
s=s[:start]+'''    // This is a directional opportunity score, not a prediction of air
    // exchange, chamber temperature, actuator power or response time.
    float thermal_direction = 0.0F;
    if (outside_temperature_ok) {
      thermal_direction = measurements.outside_temperature_c.value - temperature;
      const bool thermal_benefit =
          (temperature_error > kTemperatureDeadbandC && thermal_direction < 0.0F) ||
          (temperature_error < -kTemperatureDeadbandC && thermal_direction > 0.0F);
      if (thermal_benefit) {
        request.exhaust_fan = level(
            std::min(std::abs(temperature_error), std::abs(thermal_direction)),
            kTemperatureDeadbandC, kTemperatureFullScaleC);
      }
    }

    // Moisture transport is assessed at the current indoor temperature;
    // RH alone is not evidence of wetter/drier intake. Temperature effects
    // remain a separate directional constraint, not a forecast.
    const bool worsens_temperature =
        (temperature_error > kTemperatureDeadbandC && thermal_direction > 0.0F) ||
        (temperature_error < -kTemperatureDeadbandC && thermal_direction < 0.0F);
    if ((too_humid || too_dry) && outside_temperature_ok && outside_humidity_ok &&
        !worsens_temperature) {
      const float inside_absolute_humidity = absoluteHumidityGm3(temperature, humidity);
      const float intake_absolute_humidity = absoluteHumidityGm3(
          measurements.outside_temperature_c.value, measurements.outside_humidity_pct.value);
      const float moisture_gap = too_humid ? inside_absolute_humidity - intake_absolute_humidity
                                           : intake_absolute_humidity - inside_absolute_humidity;
      if (moisture_gap > kAbsoluteHumidityBenefitDeadbandGm3) {
        const float benefit = level(moisture_gap, kAbsoluteHumidityBenefitDeadbandGm3,
                                    kAbsoluteHumidityBenefitFullScaleGm3);
        request.exhaust_fan =
            std::max(request.exhaust_fan, std::min(humidity_level, benefit));
      }
    }'''+s[end:]
s=s.replace('constexpr float kOutsideImprovementMargin = 0.08F;\n','')
s=s.replace('// Moisture transport is assessed at the current indoor temperature;','// Moisture transport is assessed using absolute humidity;')
p.write_text(s)
p=Path('tools/ml/climate_policy.py')
s=p.read_text()
start=s.index('            if outside_temperature_ok:',s.index('        if caps.exhaust_fan.available:'))
end=s.index('\n        return ClimateAction.from_mapping(values).clipped()',start)
s=s[:start]+'''            thermal_direction = 0.0
            if outside_temperature_ok:
                thermal_direction = state.outside_temperature_c - state.air_temperature_c
                thermal_benefit = (
                    temperature_error > cfg.temperature_deadband_c and thermal_direction < 0.0
                ) or (
                    temperature_error < -cfg.temperature_deadband_c and thermal_direction > 0.0
                )
                if thermal_benefit:
                    values["exhaust_fan"] = _level(
                        min(abs(temperature_error), abs(thermal_direction)),
                        cfg.temperature_deadband_c,
                        cfg.temperature_full_scale_c,
                    )

            worsens_temperature = (
                temperature_error > cfg.temperature_deadband_c and thermal_direction > 0.0
            ) or (
                temperature_error < -cfg.temperature_deadband_c and thermal_direction < 0.0
            )
            if (
                (too_humid or too_dry)
                and outside_temperature_ok and outside_humidity_ok and not worsens_temperature
            ):
                inside_absolute_humidity = _absolute_humidity_g_m3(
                    state.air_temperature_c, state.relative_humidity_pct
                )
                intake_absolute_humidity = _absolute_humidity_g_m3(
                    state.outside_temperature_c, state.outside_humidity_pct
                )
                moisture_gap = (
                    inside_absolute_humidity - intake_absolute_humidity if too_humid
                    else intake_absolute_humidity - inside_absolute_humidity
                )
                if moisture_gap > 0.5:
                    values["exhaust_fan"] = max(
                        values["exhaust_fan"], min(humidity_level, _level(moisture_gap, 0.5, 3.0))
                    )

        co2_ok = _usable("co2_ppm", state.co2_ppm, statuses, timeout)
        if targets.co2_enabled and co2_ok:
            co2_error = targets.co2_ppm - state.co2_ppm
            if co2_error > cfg.co2_deadband_ppm and caps.co2_doser.available:
                values["co2_doser"] = _level(
                    co2_error, cfg.co2_deadband_ppm, cfg.co2_full_scale_ppm
                )
            elif (
                co2_error < -cfg.co2_deadband_ppm
                and state.co2_ppm < ClimateSafetyLimits().maximum_co2_ppm
                and caps.exhaust_fan.available
            ):
                values["exhaust_fan"] = max(
                    values["exhaust_fan"],
                    _level(co2_error, cfg.co2_deadband_ppm, cfg.co2_full_scale_ppm),
                )
'''+s[end:]
